#include <vector>
#include <cstddef>

std::vector<float> decimate_fir(const std::vector<float>& x,
                                const std::vector<float>& h, int M) {
    const int L = (int)h.size();
    const size_t N = x.size();
    const size_t outN = (N + M - 1) / M;          // ceil(N/M)
    std::vector<float> y(outN, 0.0f);
    for (size_t n = 0; n < outN; ++n) {
        long base = (long)n * M;                  // y[n] aligned to x[n*M]
        float acc = 0.0f;
        for (int k = 0; k < L; ++k) {
            long idx = base - k;                  // y[n]=sum h[k]*x[nM-k]
            if (idx >= 0 && idx < (long)N)
                acc += h[k] * x[idx];
        }
        y[n] = acc;
    }
    return y;
}
